def total_with_tax(price, rate):
    return round(price * (1 + rate), 2)


cases = [((100, 0.2), 120.0), ((50, 0.1), 55.0), ((10, 0), 10), ((3, 0.5), 5)]
passed = 0
for args, expected in cases:
    got = total_with_tax(*args)
    ok = got == expected
    passed += ok
    print(args, got, "ок" if ok else "ОШИБКА")
print(passed, "из", len(cases))
